use std::collections::BTreeSet;

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only mark items as seen when the digest actually went out; otherwise
        // they must remain unseen so the next run can consider them again.
        if published.published {
            // Deduplicate ids so each one is written and counted once.
            let ids: BTreeSet<&str> = published
                .considered
                .iter()
                .map(String::as_str)
                .collect();

            for id in ids {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
